path_perm:
    .zero 24
    
path_orient:
    .zero 24

candidate_perm:
    .zero 24

candidate_orient:
    .zero 24
    
perm_face_offset:
    .word 0, 10080, 20160

orient_face_offset:
    .word 0, 1458, 2916
    
next_move:
    .zero 12

path_h:
    .zero 12
    
move_face:
    .byte 0, 0, 0, 1, 1, 1, 2, 2, 2
    
path_move:
    .zero 11
    face_first_move:
    .byte 0, 3, 6
    


move_text:
    .byte 82,  0, 0, 0    # R
    .byte 82, 50, 0, 0    # R2
    .byte 82, 39, 0, 0    # R'
    .byte 66,  0, 0, 0    # B
    .byte 66, 50, 0, 0    # B2
    .byte 66, 39, 0, 0    # B'
    .byte 68,  0, 0, 0    # D
    .byte 68, 50, 0, 0    # D2
    .byte 68, 39, 0, 0    # D'

input_state:
    .asciz "21345671111111"
    
    input_perm:
    .zero 7
    
    input_orient:
    .zero 7
.text
main:
    
    la   t0, input_state
    la   t1, input_perm
    li   t2, 7
    la   t0, input_state
    la   t1, input_perm
    li   t2, 7
    li   t5, 0              # 已出現編號的 bitmask
parse_perm_loop:
    lbu  t3, 0(t0)
    addi t3, t3, -49

    li   t4, 7
    bgeu t3, t4, input_invalid

    # 產生目前編號對應的 bit
    li   t4, 1
    sll  t4, t4, t3

    # 該 bit 已經是 1，表示編號重複
    and  t6, t5, t4
    bne  t6, x0, input_invalid

    # 記錄這個編號已出現
    or   t5, t5, t4
    
    sb   t3, 0(t1)

    addi t0, t0, 1
    addi t1, t1, 1
    addi t2, t2, -1
    bnez t2, parse_perm_loop
    
      la   t1, input_orient
    li   t2, 7
     li   t5, 0              # 方向總和

parse_orient_loop:
    lbu  t3, 0(t0)
    addi t3, t3, -49

    li   t4, 3
    bgeu t3, t4, input_invalid
    add  t5, t5, t3         # 累加轉換後的方向值
    sb   t3, 0(t1)
    addi t0, t0, 1
    addi t1, t1, 1
    addi t2, t2, -1
    bnez t2, parse_orient_loop
        # 十四個字元之後必須是字串結尾
    lbu  t3, 0(t0)
    bne  t3, x0, input_invalid
     # 用重複減法計算方向總和除以 3 的餘數
    li   t4, 3

parse_twist_check:
    bltu t5, t4, parse_twist_done
    addi t5, t5, -3
    j    parse_twist_check

parse_twist_done:
    bne  t5, x0, input_invalid

    #計算 permutation rank
    la  t0, input_perm
    li  t2, 0                   # 目前位置 i
    li  t5, 0                   # 累積 rank

rank_perm_outer:
    add t1, t0, t2
    lbu t3, 0(t1)               # input_perm[i]

    addi t4, t2, 1              # 從右邊第一個位置開始
    li   t6, 0                  # 右邊較小編號的數量

rank_perm_count:
    li   a3, 7
    bgeu t4, a3, rank_perm_accumulate

    add  a3, t0, t4
    lbu  a4, 0(a3)
    sltu a4, a4, t3             # 右邊編號較小，得到 1
    add  t6, t6, a4

    addi t4, t4, 1
    j    rank_perm_count

rank_perm_accumulate:
    # rank = rank * (7 - i) + smaller
    # 用重複加法代替乘法
    li  a5, 7
    sub a5, a5, t2
    li  a6, 0

rank_perm_multiply:
    add  a6, a6, t5
    addi a5, a5, -1
    bne  a5, x0, rank_perm_multiply

    add  t5, a6, t6
    addi t2, t2, 1

    li   a3, 7
    bltu t2, a3, rank_perm_outer

rank_perm_done:
    nop                   
        # t5 保留 permutation rank
    la  t0, input_orient
    li  t2, 6
    li  t6, 0                   # orientation rank

rank_orient_loop:
    lbu  t3, 0(t0)

    slli t4, t6, 1              # 2 * o
    add  t6, t6, t4             # 3 * o
    add  t6, t6, t3             # 加入目前方向

    addi t0, t0, 1
    addi t2, t2, -1
    bne  t2, x0, rank_orient_loop

rank_orient_done:
    nop                         # 可在此設斷點

    # 將解析得到的 rank 存成搜尋起點
    la  t0, path_perm
    sh  t5, 0(t0)

    la  t0, path_orient
    sh  t6, 0(t0)


la t0,input_state
lbu t1,0(t0)
addi t1, t1, -49
la t2,input_perm
sb t1,0(t2)
nop





    la t0, next_move
    sb x0, 0(t0)
    li s0, 0
    la s6, permutation
    la s7, orientation
    la s8, perm_dist
    la s9, orient_dist
    la a0, path_perm
    la a1, path_orient
    la a2, candidate_perm
    la a3, candidate_orient
    la a4, next_move
    la a5, move_face
    la a6, face_first_move
    la a7, path_move
    la s10, perm_face_offset
    la s11, orient_face_offset

    slli t3,s0,1
    la t0,path_perm
    add t0,t0,t3
    lhu t1,0(t0)
    la t0,path_orient
    add t0,t0,t3
    lhu t2,0(t0)
    # t3 = perm_dist[t1]
    la  t0, perm_dist
    add t0, t0, t1
    lbu t3, 0(t0)

    # t4 = orient_dist[t2]
    la  t0, orient_dist
    add t0, t0, t2
    lbu t4, 0(t0)

    # t5 = max(t3, t4)
    mv  t5, t3
    bge t3, t4, heuristic_done
    mv  t5, t4

heuristic_done:
    mv s1, t5
    la t0,path_h
    sb t5,0(t0)
search_loop:
    # 每個 uint16_t 元素占 2 bytes
    slli t3, s0, 1

    # t1 = path_perm[depth]
    add t0, a0, t3
    lhu  t1, 0(t0)

    # t2 = path_orient[depth]
    add t0, a1, t3
    lhu  t2, 0(t0)


    # 是否已還原
    or  t6, t1, t2
    beq t6, x0, search_found

    # 已到深度上限
    bge s0, s1, search_backtrack

    # 讀取下一個候選動作
    la  t0, next_move
    add t0, t0, s0
    lbu s2, 0(t0)

    # 本層動作已全部試完
    li  t6, 9
    bge s2, t6, search_backtrack

    # 更新下次要嘗試的動作
    addi t6, s2, 1
    sb   t6, 0(t0)

    # 本次動作的面
    add t0, a5, s2
    lbu s3, 0(t0)

    # 起點沒有上一個動作
    beq s0, x0, candidate_prepare

    # 上一個動作
    addi t6, s0, -1
    la   t0, path_move
    add  t0, t0, t6
    lbu  t4, 0(t0)

    # 排除連續轉同一面
    add t0, a5, t4
    lbu t4, 0(t0)
    beq t4, s3, skip_same_face

candidate_prepare:
    add t0, a6, s3
    lbu t4, 0(t0)
    bne s2, t4, candidate_turn

    slli t3, s0, 1
    add  t0, a2, t3
    sh   t1, 0(t0)
    add  t0, a3, t3
    sh   t2, 0(t0)
candidate_turn:
    slli t3, s0, 1

    add  t0, a2, t3
    lhu  t1, 0(t0)

    add  t0, a3, t3
    lhu  t2, 0(t0)
    slli t3,s3,2
    add t0, s10, t3
    lw s4, 0(t0)
    add t0, s11, t3
    lw s5, 0(t0)
    slli t3,t1,1
    add t0, s6, s4
    add t0,t0,t3
    lhu t1,0(t0)
    slli t3,t2,1
    add t0, s7, s5
    add t0,t0,t3
    lhu t2,0(t0)
    slli t3, s0, 1
    add  t0, a2, t3
    sh   t1, 0(t0)
    add  t0, a3, t3
    sh   t2, 0(t0)

    # 排列距離
    add t0, s8, t1
    lbu t3, 0(t0)

    # 方向距離
    add t0, s9, t2
    lbu t4, 0(t0)

    # t5 = 兩個距離的較大值
    mv  t5, t3
    bge t3, t4, child_h_done
    mv  t5, t4
child_h_done:
    addi t6, s0, 1
    add  t3, t6, t5
    blt  s1, t3, search_loop

    add t0, a7, s0
    sb s2,0(t0)
    addi t6, s0, 1
    slli t3, t6, 1

    # 保存下一層排列
    add t0, a0, t3
    sh  t1, 0(t0)

    # 保存下一層方向
    add t0, a1, t3
    sh  t2, 0(t0)
    # path_h[depth + 1] = t5
    la t0, path_h
    add t0, t0, t6
    sb t5, 0(t0)
    addi s0, s0, 1
    la   t0, next_move
    add  t0, t0, s0
    sb   x0, 0(t0)
    j  search_loop

search_found:
    mv a0, s0
    j search_end

skip_same_face:
    la   t0, face_first_move
    add  t0, t0, s3
    lbu  t6, 0(t0)
    addi t6, t6, 3

    add t0, a4, s0
    sb  t6, 0(t0)
    j   search_loop

search_backtrack:
    beq  s0, x0, search_next_bound
    addi s0, s0, -1
    j    search_loop

search_next_bound:
    addi s1,s1,1
    li t6,11
    blt t6,s1,search_failed

    la t0,next_move
    sb x0,0(t0)
    j search_loop

search_failed:
    li a2, 1
    li a0, -1
    j search_end

search_end:
    mv s6, a0
    blt s6, x0, print_exit

    jal ra, verify_returned_path
    bne a2, x0, print_exit


    li s7, 0

print_loop:
    bge s7, s6, print_newline
    beq s7, x0, print_move

    li a0, 32
    li a7, 11
    ecall

print_move:
    la t0, path_move
    add t0, t0, s7
    lbu t4, 0(t0)

    slli t3, t4, 2
    la a0, move_text
    add a0, a0, t3

    li a7, 4
    ecall

    addi s7, s7, 1
    j print_loop

print_newline:
    li a0, 10
    li a7, 11
    ecall

print_exit:
    mv a0, s6

    la t0, path_move
    lbu a1, 0(t0)

    li a7, 10
    ecall
    j target_program_end
	




# Common target replay check: s6 = length; a2 = 0 success, 1 failure.
# Leaf helper; clobbers t0..t6 and a3..a7, preserves s registers.
verify_returned_path:
    li a2, 1
    blt s6, x0, target_replay_return
    li t6, 11
    blt t6, s6, target_replay_return
    la t0, path_perm
    lhu t1, 0(t0)
    la t0, path_orient
    lhu t2, 0(t0)
    li a3, 0

target_replay_loop:
    bge a3, s6, target_replay_done
    la t0, path_move
    add t0, t0, a3
    lbu t4, 0(t0)
    li t6, 9
    bgeu t4, t6, target_replay_return
    la t0, move_face
    add t0, t0, t4
    lbu a4, 0(t0)
    la t0, face_first_move
    add t0, t0, a4
    lbu t6, 0(t0)
    sub a5, t4, t6
    addi a5, a5, 1
    slli t3, a4, 2
    la t0, perm_face_offset
    add t0, t0, t3
    lw a6, 0(t0)
    la t0, orient_face_offset
    add t0, t0, t3
    lw a7, 0(t0)

target_replay_turn:
    slli t3, t1, 1
    la t0, permutation
    add t0, t0, a6
    add t0, t0, t3
    lhu t1, 0(t0)
    slli t3, t2, 1
    la t0, orientation
    add t0, t0, a7
    add t0, t0, t3
    lhu t2, 0(t0)
    addi a5, a5, -1
    bne a5, x0, target_replay_turn
    addi a3, a3, 1
    j target_replay_loop

target_replay_done:
    or t6, t1, t2
    sltu a2, x0, t6

target_replay_return:
    ret

input_invalid:
    li a0, -1
    li a2, 1
    li a7, 10
    ecall
    j target_program_end
target_program_end:

    nop
